#!/usr/bin/env node
import { createClient } from '@supabase/supabase-js';
import fs from 'fs';

const supabase = createClient(
  'https://mhfikaomkmqcndqfohbp.supabase.co',
  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1oZmlrYW9ta21xY25kcWZvaGJwIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc0MzYxNzkxMiwiZXhwIjoyMDU5MTkzOTEyfQ.DMyPlyn0d5RvluhrG8zrjzThCaJGlw9DrJ74GliDql8'
);

// This file will contain the actual Japanese translations
// Generated by Claude's translation capabilities
import { translations } from './ja-translations-data.mjs';

const EEAT_JA = '*公開日：2026年2月16日 | 更新日：2026年2月20日 | 著者：Mystery Maker Party チーム | 次回レビュー：2026年5月20日*';

async function translateAndInsert() {
  const posts = JSON.parse(fs.readFileSync('posts-to-translate-ja.json', 'utf-8'));

  console.log(`\n🇯🇵 Starting Japanese translation and insertion of ${posts.length} posts\n`);

  let successCount = 0;
  let skipCount = 0;
  let errorCount = 0;

  for (let i = 0; i < posts.length; i++) {
    const post = posts[i];
    const postNum = i + 6;
    const jaSlug = `ja-${post.slug}`;

    try {
      // Check if already exists
      const { data: existing } = await supabase
        .from('blog_posts')
        .select('id')
        .eq('slug', jaSlug)
        .single();

      if (existing) {
        console.log(`⏭️  #${postNum} exists: ${post.slug.substring(0, 40)}...`);
        skipCount++;
        continue;
      }

      // Get translation from data file
      const translation = translations[post.slug];

      if (!translation) {
        console.error(`❌ #${postNum} No translation found: ${post.slug}`);
        errorCount++;
        continue;
      }

      // Replace E-E-A-T
      let jaContent = post.content.replace(
        /\*Published:.*?\*\n\n\*Based on.*?\*/s,
        EEAT_JA
      );

      // Apply translated content
      jaContent = translation.content || jaContent;

      // Create Japanese post
      const jaPost = {
        title: translation.title,
        slug: jaSlug,
        content: jaContent,
        meta_description: translation.meta_description,
        meta_keywords: translation.meta_keywords,
        language: 'ja',
        theme: post.theme,
        status: 'published',
        reading_time: post.reading_time,
        author: 'Mystery Maker Party チーム',
        tags: post.tags,
        published_at: new Date().toISOString(),
        post_date: '2026-02-22',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };

      // Insert to database
      const { data, error } = await supabase
        .from('blog_posts')
        .insert([jaPost])
        .select();

      if (error) throw error;

      console.log(`✅ #${postNum} ${post.slug.substring(0, 40)}...`);
      successCount++;

      // Progress report every 5
      if (postNum % 5 === 0) {
        console.log(`\n✅ Posts ${postNum - 4}-${postNum} completed\n`);
      }

    } catch (error) {
      console.error(`❌ #${postNum} Error: ${error.message}`);
      errorCount++;
    }

    // Small delay to avoid rate limiting
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  console.log(`\n${'='.repeat(60)}`);
  console.log(`✅ Japanese Translation Complete!`);
  console.log(`${'='.repeat(60)}`);
  console.log(`Total posts processed: ${posts.length}`);
  console.log(`Successfully inserted: ${successCount}`);
  console.log(`Already existed: ${skipCount}`);
  console.log(`Errors: ${errorCount}`);
  console.log(`${'='.repeat(60)}\n`);
}

translateAndInsert().catch(console.error);
